UPDATE TB_M1_INFO_USER SET user_nm = #{userNm}, user_id = #{userId}, user_lv = #{userLv}, email = #{email}, phone = #{phone}, part_nm = #{partNm},
user_pwd = #{userPwd},
upt_dt = sysdate WHERE user_sq = #{userSq}

mapper.sql:
SELECT ROWNUM as "rownum", ROW_NUMBER() OVER (ORDER BY user_sq) as num, b.site_nm as "siteNm", a.user_sq as "userSq", a.user_nm as "userNm", a.user_lv as "userLv",
case a.user_lv when '1' then '일반 사용자' when '5' then '시스템 관리자' end "userLvStr",
a.user_id as "userId", a.email as "email", a.phone as "phone", a.part_nm as "partNm" --a.alarm_cd as "alarmCd" --a.use_cd as "useCd" FROM tb_m1_info_user a JOIN tb_m1_info_site b ON a.site_sq = b.site_sq
WHERE b.site_sq = #{siteSq}
AND a.use_cd = #{useCd}
AND ( user_id like '%' || #{searchParam} || '%' OR user_nm like '%' || #{searchParam} || '%' )
